def transform(grid):
    """Turn large solid rectangular color patches into color 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Find maximal same-color rectangles by extending equal runs downward.
    # The embedded patches are solid rectangles at least 4 rows by 5 columns.
    for top in range(h):
        for left in range(w):
            color = grid[top][left]
            width = 0
            while left + width < w and grid[top][left + width] == color:
                width += 1
            # For each possible right edge, track the consecutive rows that
            # preserve the same-color span and paint qualifying rectangles.
            for right in range(left + 4, left + width):
                bottom = top
                while bottom < h and all(grid[bottom][c] == color
                                         for c in range(left, right + 1)):
                    bottom += 1
                if bottom - top >= 4:
                    for r in range(top, bottom):
                        for c in range(left, right + 1):
                            out[r][c] = 4
    return out
